var EquipmentAvailabilityChecker = Class.create();
EquipmentAvailabilityChecker.prototype = {
    initialize: function() {},

    isEquipmentAvailable: function(equipmentId) {
        var gr = new GlideRecord('x_acme_eqchk_request');
        gr.addQuery('equipment', equipmentId);
        gr.addQuery('state', 'IN', '2,3');
        gr.addQuery('active', true);
        gr.query();
        return !gr.hasNext();
    },

    type: 'EquipmentAvailabilityChecker'
};

(function executeRule(current, previous) {
    var checker = new x_acme_eqchk.EquipmentAvailabilityChecker();

    if (!checker.isEquipmentAvailable(current.equipment.toString())) {
        gs.addErrorMessage('Equipment already checked out.');
        current.setAbortAction(true);
    }
})(current, previous);

// Wrapper Script Include (extends AbstractAjaxProcessor)
isEquipmentAvailable: function() {
    var id = this.getParameter('sysparm_equipment_id');
    return new x_acme_eqchk.EquipmentAvailabilityChecker()
        .isEquipmentAvailable(id);
}

// Client Script, onChange of "equipment"
ga.getXMLAnswer(function(answer) {
    if (answer === 'false') {
        g_form.addErrorMessage('Already checked out.');
    }
});
